diff --git a/sched/plan_test.go b/sched/plan_test.go
new file mode 100644
index 0000000..1daec59
--- /dev/null
+++ b/sched/plan_test.go
@@ -0,0 +1,161 @@
+package sched
+
+import (
+	"errors"
+	"fmt"
+	"reflect"
+	"testing"
+	"time"
+)
+
+func TestPlanBatches(t *testing.T) {
+	got, err := Plan(map[string][]string{
+		"app":  {"lib", "util", "lib"},
+		"lib":  {"util"},
+		"util": nil,
+		"doc":  {},
+	})
+	if err != nil {
+		t.Fatal(err)
+	}
+	want := [][]string{{"doc", "util"}, {"lib"}, {"app"}}
+	if !reflect.DeepEqual(got, want) {
+		t.Fatalf("Plan = %v, want %v", got, want)
+	}
+}
+
+func TestPlanEmpty(t *testing.T) {
+	got, err := Plan(nil)
+	if err != nil || got == nil || len(got) != 0 {
+		t.Fatalf("Plan(nil) = %v, %v", got, err)
+	}
+}
+
+func TestPlanUnknownDepWinsOverCycle(t *testing.T) {
+	_, err := Plan(map[string][]string{
+		"a": {"b"},
+		"b": {"a"},
+		"z": {"q", "m"},
+		"y": {"x"},
+	})
+	var ue *UnknownDepError
+	if !errors.As(err, &ue) || ue.Task != "y" || ue.Dep != "x" {
+		t.Fatalf("err = %v", err)
+	}
+	if want := `task "y" depends on unknown task "x"`; err.Error() != want {
+		t.Fatalf("Error() = %q", err.Error())
+	}
+}
+
+func TestPlanCyclePaths(t *testing.T) {
+	cases := []struct {
+		name string
+		g    map[string][]string
+		want string
+	}{
+		{"self", map[string][]string{"b": {"b"}}, "dependency cycle: b -> b"},
+		{"pair", map[string][]string{"a": {"b"}, "b": {"a"}}, "dependency cycle: a -> b -> a"},
+		{"canonical", map[string][]string{
+			"p": {"r", "q"}, "q": {"s"}, "s": {"p"}, "r": {"p"},
+		}, "dependency cycle: p -> q -> s -> p"},
+	}
+	for _, c := range cases {
+		_, err := Plan(c.g)
+		var ce *CycleError
+		if !errors.As(err, &ce) || err.Error() != c.want {
+			t.Fatalf("%s: err = %v, want %q", c.name, err, c.want)
+		}
+	}
+}
+
+func TestSimulateBasic(t *testing.T) {
+	s, err := Simulate(map[string]Task{
+		"a": {Duration: 3},
+		"b": {Duration: 2, Deps: []string{"a"}},
+		"c": {Duration: 5},
+	}, 2)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if s.Makespan != 5 {
+		t.Fatalf("Makespan = %d", s.Makespan)
+	}
+	// c (longer) is taken first and gets the lowest free worker, 0.
+	if want := (Slot{Start: 0, End: 3, Worker: 1}); s.Slots["a"] != want {
+		t.Fatalf("a = %+v", s.Slots["a"])
+	}
+	if want := (Slot{Start: 3, End: 5, Worker: 1}); s.Slots["b"] != want {
+		t.Fatalf("b = %+v", s.Slots["b"])
+	}
+	if want := (Slot{Start: 0, End: 5, Worker: 0}); s.Slots["c"] != want {
+		t.Fatalf("c = %+v", s.Slots["c"])
+	}
+	if want := []string{"a", "b"}; !reflect.DeepEqual(s.CriticalPath, want) {
+		t.Fatalf("CriticalPath = %v", s.CriticalPath)
+	}
+}
+
+func TestSimulateErrors(t *testing.T) {
+	if _, err := Simulate(map[string]Task{"a": {Duration: 1}}, 0); !errors.Is(err, ErrNoWorkers) {
+		t.Fatalf("err = %v", err)
+	}
+	_, err := Simulate(map[string]Task{"b": {Duration: 0}, "a": {Duration: -1}}, 1)
+	var de *InvalidDurationError
+	if !errors.As(err, &de) || de.Task != "a" {
+		t.Fatalf("err = %v", err)
+	}
+}
+
+func TestSimulateEmpty(t *testing.T) {
+	s, err := Simulate(nil, 4)
+	if err != nil || s.Slots == nil || len(s.Slots) != 0 || s.Makespan != 0 || s.CriticalPath == nil {
+		t.Fatalf("Simulate(nil) = %+v, %v", s, err)
+	}
+}
+
+func TestLargeChainAndRing(t *testing.T) {
+	const n = 200000
+	chain := make(map[string][]string, n)
+	tasks := make(map[string]Task, n)
+	for i := 0; i < n; i++ {
+		name := fmt.Sprintf("t%07d", i)
+		var deps []string
+		if i > 0 {
+			deps = []string{fmt.Sprintf("t%07d", i-1)}
+		}
+		chain[name] = deps
+		tasks[name] = Task{Deps: deps, Duration: 1}
+	}
+	start := time.Now()
+	if _, err := Plan(chain); err != nil {
+		t.Fatal(err)
+	}
+	if _, err := Simulate(tasks, 8); err != nil {
+		t.Fatal(err)
+	}
+	if d := time.Since(start); d > 2*time.Second {
+		t.Fatalf("too slow: %v", d)
+	}
+
+	ring := make(map[string][]string, n)
+	for i := 0; i < 100000; i++ {
+		ring[fmt.Sprintf("r%07d", i)] = []string{fmt.Sprintf("r%07d", (i+1)%100000)}
+	}
+	for i := 0; i < 100000; i++ {
+		dep := "r0000000"
+		if i < 99999 {
+			dep = fmt.Sprintf("c%07d", i+1)
+		}
+		ring[fmt.Sprintf("c%07d", i)] = []string{dep}
+	}
+	ring["zz"] = nil
+	start = time.Now()
+	_, err := Plan(ring)
+	if d := time.Since(start); d > 2*time.Second {
+		t.Fatalf("cycle report too slow: %v", d)
+	}
+	var ce *CycleError
+	if !errors.As(err, &ce) || ce.Path[0] != "r0000000" {
+		t.Fatalf("err = %v", err)
+	}
+}

