+use exprkit::{eval, EvalError};
+use std::collections::HashMap;
+
+fn run(s: &str) -> Result<f64, EvalError> {
+    eval(s, &HashMap::new())
+}
+
+fn with_x(s: &str, x: f64) -> Result<f64, EvalError> {
+    let mut vars = HashMap::new();
+    vars.insert("x".to_string(), x);
+    vars.insert("y".to_string(), 5.0);
+    eval(s, &vars)
+}
+
+#[test]
+fn precedence_and_signs() {
+    assert_eq!(run("-2^2"), Ok(-4.0));
+    assert_eq!(run("(-2)^2"), Ok(4.0));
+    assert_eq!(run("2^-1"), Ok(0.5));
+    assert_eq!(run("2^3^2"), Ok(512.0));
+    assert_eq!(run("--3"), Ok(3.0));
+    assert_eq!(run("2--2"), Ok(4.0));
+    assert_eq!(run("7 % 4 % 2"), Ok(1.0));
+    assert_eq!(run("-7 % 3"), Ok(-1.0));
+    assert_eq!(run("7.5 % 2"), Ok(1.5));
+    assert_eq!(run("007 + 0.5 + 10.25"), Ok(17.75));
+}
+
+#[test]
+fn implicit_multiplication() {
+    assert_eq!(with_x("2x", 3.0), Ok(6.0));
+    assert_eq!(with_x("2 x", 3.0), Ok(6.0));
+    assert_eq!(with_x("x y", 3.0), Ok(15.0));
+    assert_eq!(run("2(3+4)"), Ok(14.0));
+    assert_eq!(run("(1+2)(3+4)"), Ok(21.0));
+    assert_eq!(run("2(3)(4)"), Ok(24.0));
+    assert_eq!(run("3abs(-2)"), Ok(6.0));
+    assert_eq!(with_x("2x^2", 3.0), Ok(18.0));
+    assert_eq!(with_x("-2x", 3.0), Ok(-6.0));
+    assert_eq!(with_x("2^3x", 3.0), Ok(24.0));
+    assert_eq!(run("6/2(1+2)"), Ok(9.0));
+}
+
+#[test]
+fn functions() {
+    assert_eq!(run("min(3, 1, 2)"), Ok(1.0));
+    assert_eq!(run("max(3, 1, 2)"), Ok(3.0));
+    assert_eq!(run("abs(-4)"), Ok(4.0));
+    assert_eq!(run("sqrt(16)"), Ok(4.0));
+    assert_eq!(run("sqrt(-1)"), Err(EvalError::Domain("sqrt".into())));
+    assert_eq!(run("min()"), Err(EvalError::Arity { name: "min".into(), expected: "at least 1".into(), got: 0 }));
+    assert_eq!(run("abs(1, 2)"), Err(EvalError::Arity { name: "abs".into(), expected: "1".into(), got: 2 }));
+    assert_eq!(run("foo(y)"), Err(EvalError::UnknownFunc("foo".into())));
+    assert_eq!(run("y(1)"), Err(EvalError::UnknownFunc("y".into())));
+}
+
+#[test]
+fn errors_and_positions() {
+    assert_eq!(run(".5"), Err(EvalError::Parse { pos: 0 }));
+    assert_eq!(run("5."), Err(EvalError::Parse { pos: 1 }));
+    assert_eq!(run("2 3"), Err(EvalError::Parse { pos: 2 }));
+    assert_eq!(run("(2)3"), Err(EvalError::Parse { pos: 3 }));
+    assert_eq!(run("x 2"), Err(EvalError::Parse { pos: 2 }));
+    assert_eq!(run("1 + 2)"), Err(EvalError::Parse { pos: 5 }));
+    assert_eq!(run("()"), Err(EvalError::Parse { pos: 1 }));
+    assert_eq!(run("X"), Err(EvalError::Parse { pos: 0 }));
+    assert_eq!(run("1,2"), Err(EvalError::Parse { pos: 1 }));
+    assert_eq!(run("min(1 2)"), Err(EvalError::Parse { pos: 6 }));
+    assert_eq!(run("min(,1)"), Err(EvalError::Parse { pos: 4 }));
+    assert_eq!(run("min(1,)"), Err(EvalError::Parse { pos: 6 }));
+    assert_eq!(run(""), Err(EvalError::Parse { pos: 0 }));
+    assert_eq!(run("   "), Err(EvalError::Parse { pos: 3 }));
+    assert_eq!(run("(1 + 2"), Err(EvalError::Parse { pos: 6 }));
+    assert_eq!(run("1 +"), Err(EvalError::Parse { pos: 3 }));
+    assert_eq!(run("max(1"), Err(EvalError::Parse { pos: 5 }));
+    // A parse error wins over an evaluation error that comes earlier.
+    assert_eq!(run("z + 1 )"), Err(EvalError::Parse { pos: 6 }));
+}
+
+#[test]
+fn evaluation_errors() {
+    assert_eq!(with_x("q + 1", 1.0), Err(EvalError::UnknownVar("q".into())));
+    assert_eq!(run("1 / 0"), Err(EvalError::DivByZero));
+    assert_eq!(run("1 % -0.0"), Err(EvalError::DivByZero));
+    assert_eq!(run("1 / 0 + q"), Err(EvalError::DivByZero));
+}
+
+#[test]
+fn deep_inputs_do_not_overflow() {
+    let n = 100_000;
+    let parens = format!("{}1{}", "(".repeat(n), ")".repeat(n));
+    assert_eq!(run(&parens), Ok(1.0));
+
+    let abs_calls = format!("{}-3{}", "abs(".repeat(n), ")".repeat(n));
+    assert_eq!(run(&abs_calls), Ok(3.0));
+
+    let max_calls = format!("{}5{}", "max(1, ".repeat(n), ")".repeat(n));
+    assert_eq!(run(&max_calls), Ok(5.0));
+
+    let signs = format!("{}1", "-".repeat(n));
+    assert_eq!(run(&signs), Ok(1.0));
+
+    let chain = format!("{}1", "1^".repeat(n));
+    assert_eq!(run(&chain), Ok(1.0));
+
+    let sum = vec!["1"; 200_000].join("+");
+    assert_eq!(run(&sum), Ok(200_000.0));
+
+    let repeated = "(1)".repeat(n);
+    assert_eq!(run(&repeated), Ok(1.0));
+}

 IntervalSet::new();
+    s.insert(Bound::Closed(1), Bound::Open(3));
+    s.insert(Bound::Closed(3), Bound::Closed(5));
+    s.insert(Bound::Closed(10), Bound::Closed(10));
+    assert_eq!(s.measure(), 4);
+}
+
+#[test]
+fn complement_flips_endpoints_within_window() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(2), Bound::Open(4));
+    s.insert(Bound::Open(6), Bound::Closed(8));
+    assert_eq!(
+        s.complement(Bound::Closed(0), Bound::Closed(10)),
+        vec![
+            (Bound::Closed(0), Bound::Open(2)),
+            (Bound::Closed(4), Bound::Closed(6)),
+            (Bound::Open(8), Bound::Closed(10)),
+        ]
+    );
+    assert_ne!(
+        s.complement(Bound::Closed(0), Bound::Closed(10)),
+        vec![(Bound::Closed(0), Bound::Closed(10))]
+    );
+}
+
+#[test]
+fn complement_is_empty_for_empty_or_covered_window() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(0), Bound::Closed(10));
+    assert_eq!(
+        s.complement(Bound::Closed(2), Bound::Closed(5)),
+        Vec::<(Bound, Bound)>::new()
+    );
+    assert_eq!(
+        s.complement(Bound::Open(2), Bound::Open(2)),
+        Vec::<(Bound, Bound)>::new()
+    );
+    let e = IntervalSet::new();
+    assert_eq!(
+        e.complement(Bound::Closed(0), Bound::Closed(1)),
+        vec![(Bound::Closed(0), Bound::Closed(1))]
+    );
+}
+
+#[test]
+fn extreme_i64_endpoints_do_not_overflow() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(i64::MIN), Bound::Closed(i64::MAX));
+    assert!(!s.is_empty());
+    assert!(s.contains(i64::MIN as f64));
+    assert!(s.contains(0.0));
+    assert_eq!(
+        s.measure(),
+        (i64::MAX as i128) - (i64::MIN as i128)
+    );
+    assert_ne!(s.measure(), 0);
+    s.remove(Bound::Closed(i64::MIN), Bound::Closed(i64::MAX));
+    assert!(s.is_empty());
+    assert_eq!(s.to_string(), "{}");
+}
+
+#[test]
+fn extreme_complement_of_empty_set_is_whole_window() {
+    let e = IntervalSet::new();
+    assert_eq!(
+        e.complement(Bound::Closed(i64::MIN), Bound::Closed(i64::MAX)),
+        vec![(Bound::Closed(i64::MIN), Bound::Closed(i64::MAX))]
+    );
+}
+
+#[test]
+fn large_workload_runs_within_time_budget() {
+    let mut state: u64 = 0x9E37_79B9_7F4A_7C15;
+    let mut next = move || {
+        state ^= state << 13;
+        state ^= state >> 7;
+        state ^= state << 17;
+        state
+    };
+    let mut s = IntervalSet::new();
+    let start = Instant::now();
+    for i in 0..300_000i64 {
+        let jitter = (next() % 2001) as i64 - 1000;
+        let lo = 1_000_000_000i64 - i * 3333 + jitter;
+        let len = (next() % 1001) as i64;
+        s.insert(Bound::Closed(lo), Bound::Closed(lo + len));
+        let jitter2 = (next() % 2001) as i64 - 1000;
+        let rlo = lo + jitter2;
+        s.remove(Bound::Closed(rlo), Bound::Closed(rlo + len));
+        let probe = (next() % 1_000_000_001) as f64;
+        let _ = s.contains(probe);
+    }
+    let elapsed = start.elapsed();
+    assert!(
+        elapsed.as_secs_f64() < 3.0,
+        "workload took {:?}",
+        elapsed
+    );
+    assert!(s.measure() >= 0);
+}
