+++ b/tests/set_operations.rs
@@ -0,0 +1,94 @@
+use intervalkit::{Bound, IntervalSet};
+use std::time::Instant;
+
+fn c(v: i64) -> Bound {
+    Bound::Closed(v)
+}
+fn o(v: i64) -> Bound {
+    Bound::Open(v)
+}
+
+#[test]
+fn merges_only_when_union_is_one_interval() {
+    let mut s = IntervalSet::new();
+    s.insert(c(1), o(3));
+    s.insert(c(3), c(5));
+    assert_eq!(s.ranges(), vec![(c(1), c(5))]);
+
+    let mut t = IntervalSet::new();
+    t.insert(o(1), o(3));
+    t.insert(o(3), o(5));
+    assert_eq!(t.ranges(), vec![(o(1), o(3)), (o(3), o(5))]);
+    assert_eq!(t.to_string(), "{(1,3), (3,5)}");
+
+    let mut u = IntervalSet::new();
+    u.insert(c(1), o(3));
+    u.insert(o(3), c(5));
+    assert_eq!(u.to_string(), "{[1,3), (3,5]}");
+}
+
+#[test]
+fn remove_splits_intervals() {
+    let mut s = IntervalSet::new();
+    s.insert(c(1), c(5));
+    s.remove(c(2), c(2));
+    assert_eq!(s.ranges(), vec![(c(1), o(2)), (o(2), c(5))]);
+
+    let mut t = IntervalSet::new();
+    t.insert(c(1), c(5));
+    t.remove(o(2), o(4));
+    assert_eq!(t.ranges(), vec![(c(1), c(2)), (c(4), c(5))]);
+}
+
+#[test]
+fn complement_and_display() {
+    let mut s = IntervalSet::new();
+    s.insert(c(2), o(4));
+    s.insert(o(6), c(8));
+    assert_eq!(
+        s.complement(c(0), c(10)),
+        vec![(c(0), o(2)), (c(4), c(6)), (o(8), c(10))]
+    );
+    assert!(s.complement(c(3), o(3)).is_empty());
+    assert_eq!(IntervalSet::new().to_string(), "{}");
+    let mut n = IntervalSet::new();
+    n.insert(o(-3), c(0));
+    assert_eq!(n.to_string(), "{(-3,0]}");
+}
+
+#[test]
+fn extreme_endpoints_do_not_overflow() {
+    let mut s = IntervalSet::new();
+    s.insert(c(i64::MIN), c(i64::MAX));
+    assert_eq!(s.measure(), i64::MAX as i128 - i64::MIN as i128);
+    assert!(s.contains(0.0));
+    s.remove(c(i64::MIN), o(i64::MAX));
+    assert_eq!(s.ranges(), vec![(c(i64::MAX), c(i64::MAX))]);
+}
+
+#[test]
+fn descending_workload_is_fast() {
+    let mut s = IntervalSet::new();
+    let mut seed: u64 = 0x9E37_79B9_7F4A_7C15;
+    let mut next = move || {
+        seed ^= seed << 13;
+        seed ^= seed >> 7;
+        seed ^= seed << 17;
+        seed
+    };
+    let start = Instant::now();
+    let mut pos: i64 = 1_000_000_000;
+    for _ in 0..300_000 {
+        let len = (next() % 1001) as i64;
+        let jitter = (next() % 3) as i64;
+        pos = (pos - 1 - jitter).max(0);
+        s.insert(c(pos), c(pos + len));
+        s.remove(c(pos + len / 2), c(pos + len / 2 + 1));
+        let x = (next() % 1_000_000_001) as f64;
+        let _ = s.contains(x);
+        if pos == 0 {
+            break;
+        }
+    }
+    assert!(start.elapsed().as_secs_f64() < 3.0);
+}

