+use romankit::roman::{from_roman, to_roman, RomanError};
+
+#[test]
+fn to_roman_rejects_out_of_range() {
+    assert_eq!(to_roman(0), Err(RomanError::OutOfRange));
+    assert_eq!(to_roman(4000), Err(RomanError::OutOfRange));
+    assert_eq!(to_roman(1).unwrap(), "I");
+    assert_eq!(to_roman(3999).unwrap(), "MMMCMXCIX");
+}
+
+#[test]
+fn from_roman_parses_subtractive_endings() {
+    assert_eq!(from_roman("IV"), Ok(4));
+    assert_eq!(from_roman("XIX"), Ok(19));
+}
+
+#[test]
+fn from_roman_rejects_empty_and_invalid_chars() {
+    assert_eq!(from_roman(""), Err(RomanError::Empty));
+    assert_eq!(from_roman("xiv"), Err(RomanError::InvalidChar('x')));
+    assert_eq!(from_roman("X V"), Err(RomanError::InvalidChar(' ')));
+}
+
+#[test]
+fn from_roman_rejects_non_canonical() {
+    for s in ["IIII", "IC", "VX", "MMMM", "IIV", "XM"] {
+        assert_eq!(from_roman(s), Err(RomanError::NonCanonical), "{s}");
+    }
+}
+
+#[test]
+fn from_roman_round_trips_canonical_forms() {
+    for n in 1..=3999u32 {
+        let s = to_roman(n).unwrap();
+        assert_eq!(from_roman(&s), Ok(n), "{s}");
+    }
+}

