+    for n in 1..=3999u32 {
+        let s = to_roman(n).unwrap();
+        assert_eq!(from_roman(&s), Ok(n), "{s}");
+    }
+}
+
+#[test]
+fn from_roman_never_accepts_non_canonical_spellings() {
+    // Every string of length <= 4 over the digit alphabet: Ok iff it is the canonical form.
+    let alphabet = ['I', 'V', 'X', 'L', 'C', 'D', 'M'];
+    let mut strings = vec![String::new()];
+    for _ in 0..4 {
+        let mut next = Vec::new();
+        for prefix in &strings {
+            for &c in &alphabet {
+                next.push(format!("{prefix}{c}"));
+            }
+        }
+        strings.extend(next);
+    }
+    for s in strings.iter().filter(|s| !s.is_empty()) {
+        let expected = (1..=3999u32).find(|&n| to_roman(n).unwrap() == *s);
+        match (from_roman(s), expected) {
+            (Ok(n), Some(e)) => assert_eq!(n, e, "{s}"),
+            (Err(RomanError::NonCanonical), None) => {}
+            other => panic!("{s}: {other:?}"),
+        }
+    }
+}

