+use statkit::report::summary;
+use statkit::stats::{count, mean, median, percentile};
+
+const NAN: f64 = f64::NAN;
+
+fn close(a: Option<f64>, b: f64) -> bool {
+    match a {
+        Some(x) => (x - b).abs() < 1e-9,
+        None => false,
+    }
+}
+
+#[test]
+fn summary_reports_interpolated_percentiles() {
+    let s = summary(&[1.0, 2.0, 3.0, 4.0]);
+    assert_eq!(s, "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert_ne!(s, "n=4 mean=2.50 p50=2.00 p90=3.00");
+}
+
+#[test]
+fn summary_is_independent_of_input_order() {
+    let sorted = summary(&[1.0, 2.0, 3.0, 4.0]);
+    let shuffled = summary(&[3.0, 1.0, 4.0, 2.0]);
+    assert_eq!(shuffled, sorted);
+    assert_ne!(summary(&[4.0, 3.0, 2.0, 1.0]), "n=4 mean=2.50 p50=2.00 p90=3.00");
+}
+
+#[test]
+fn summary_of_empty_input_is_just_count() {
+    let empty: Vec<f64> = vec![];
+    assert_eq!(summary(&empty), "n=0");
+    assert_ne!(summary(&empty), "n=0 mean=NaN p50=0.00 p90=0.00");
+}
+
+#[test]
+fn nan_values_are_ignored_by_summary_and_mean() {
+    let with_nan = summary(&[1.0, NAN, 2.0, 3.0, 4.0]);
+    assert_eq!(with_nan, "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert!(!with_nan.contains("NaN"));
+    assert!(close(mean(&[1.0, NAN, 3.0]), 2.0));
+    assert_eq!(mean(&[NAN, NAN]), None);
+}
+
+#[test]
+fn count_ignores_nan_values() {
+    assert_eq!(count(&[1.0, NAN, 3.0]), 2);
+    assert_eq!(count(&[NAN, NAN]), 0);
+    assert_ne!(count(&[1.0, NAN, 3.0]), 3);
+}
+
+#[test]
+fn undefined_statistics_return_none_when_no_usable_values() {
+    let empty: Vec<f64> = vec![];
+    assert_eq!(mean(&empty), None);
+    assert_eq!(median(&empty), None);
+    assert_eq!(percentile(&empty, 50.0), None);
+    assert_eq!(median(&[NAN]), None);
+    assert_eq!(percentile(&[NAN, NAN], 90.0), None);
+    assert_eq!(summary(&[NAN, NAN]), "n=0");
+}
+
+#[test]
+fn percentile_rejects_invalid_p() {
+    let v = [1.0, 2.0, 3.0, 4.0];
+    assert_eq!(percentile(&v, NAN), None);
+    assert_eq!(percentile(&v, -0.1), None);
+    assert_eq!(percentile(&v, 100.5), None);
+    assert!(close(percentile(&v, 100.0), 4.0));
+}
+
+#[test]
+fn percentile_uses_linear_interpolation_between_closest_ranks() {
+    let v = [1.0, 2.0, 3.0, 4.0];
+    assert!(close(percentile(&v, 0.0), 1.0));
+    assert!(close(percentile(&v, 90.0), 3.7));
+    assert!(close(percentile(&v, 50.0), 2.5));
+    assert!(!close(percentile(&v, 90.0), 3.0));
+}
+
+#[test]
+fn percentile_does_not_depend_on_order_and_keeps_input() {
+    let v = vec![3.0, 1.0, 2.0];
+    let p = percentile(&v, 0.0);
+    assert!(close(p, 1.0));
+    assert_eq!(v, vec![3.0, 1.0, 2.0]);
+    assert!(close(percentile(&[2.0, 3.0, 1.0], 0.0), 1.0));
+    assert!(!close(percentile(&v, 0.0), 3.0));
+}
+
+#[test]
+fn median_is_percentile_fifty() {
+    let v = [5.0, 1.0, 3.0, 2.0];
+    assert!(close(median(&v), 2.5));
+    assert!(close(median(&v), percentile(&v, 50.0).unwrap()));
+    assert!(!close(median(&v), 2.0));
+}

