+    let before = inv.available("a");
+    assert_eq!(inv.commit(id), Ok(()));
+    assert_eq!(inv.on_hand("a"), 7);
+    assert_eq!(inv.available("a"), before);
+    assert_ne!(inv.on_hand("a"), 10);
+}
+
+#[test]
+fn release_and_commit_reject_unknown_or_finished_reservations() {
+    let mut inv = stocked(&[("a", 10)]);
+    assert_eq!(inv.release(ReservationId(999)), Err(ReserveError::UnknownReservation));
+    assert_eq!(inv.commit(ReservationId(999)), Err(ReserveError::UnknownReservation));
+
+    let released = inv.reserve(&Order::new("o1").with_line("a", 1)).unwrap();
+    assert_eq!(inv.release(released), Ok(()));
+    assert_eq!(inv.commit(released), Err(ReserveError::UnknownReservation));
+
+    let committed = inv.reserve(&Order::new("o2").with_line("a", 1)).unwrap();
+    assert_eq!(inv.commit(committed), Ok(()));
+    assert_eq!(inv.release(committed), Err(ReserveError::UnknownReservation));
+    assert_eq!(inv.on_hand("a"), 9);
+}
