+#[test]
+fn ids_are_never_reused_after_release() {
+    let mut inv = stocked(&[("a", 10)]);
+    let old = inv.reserve(&Order::new("o1").with_line("a", 1)).unwrap();
+    inv.release(old).unwrap();
+    let new = inv.reserve(&Order::new("o2").with_line("a", 1)).unwrap();
+    assert_ne!(old, new);
+    assert_eq!(inv.release(old), Err(ReserveError::UnknownReservation));
+    assert_eq!(inv.available("a"), 9);
+}
