+import { expect, test } from "bun:test";
+import { cartTotal, InvalidDiscountError } from "../src/cart";
+import { checkoutSummary } from "../src/checkout";
+
+const small = [{ sku: "mug", priceCents: 1200, qty: 2 }]; // subtotal 2400, shipping 499
+const big = [{ sku: "lamp", priceCents: 6000, qty: 1 }]; // subtotal 6000, free shipping
+
+test("undefined and empty code behave like no code", () => {
+  expect(cartTotal(small, undefined)).toBe(2899);
+  expect(cartTotal(small, "")).toBe(2899);
+});
+
+test("SAVE10 takes 10% off the subtotal, shipping still applies", () => {
+  expect(cartTotal(small, "SAVE10")).toBe(2160 + 499);
+});
+
+test("codes are case-insensitive and ignore surrounding spaces", () => {
+  expect(cartTotal(small, "  save10 ")).toBe(2160 + 499);
+});
+
+test("SAVE10 rounds to the nearest cent", () => {
+  const odd = [{ sku: "pen", priceCents: 105, qty: 1 }]; // 10% = 10.5 cents -> 11
+  expect(cartTotal(odd, "SAVE10")).toBe(94 + 499);
+});
+
+test("FLAT5 takes 500 cents off the subtotal", () => {
+  expect(cartTotal(small, "FLAT5")).toBe(1900 + 499);
+});
+
+test("FLAT5 never takes the subtotal below zero", () => {
+  const cheap = [{ sku: "pin", priceCents: 300, qty: 1 }];
+  expect(cartTotal(cheap, "FLAT5")).toBe(0 + 499);
+});
+
+test("FREESHIP waives shipping", () => {
+  expect(cartTotal(small, "FREESHIP")).toBe(2400);
+});
+
+test("free shipping eligibility uses the pre-discount subtotal", () => {
+  // 5200 before discount -> free shipping; SAVE10 takes it to 4680, still free.
+  const nearMin = [{ sku: "desk", priceCents: 5200, qty: 1 }];
+  expect(cartTotal(nearMin, "SAVE10")).toBe(4680);
+});
+
+test("unknown code throws InvalidDiscountError", () => {
+  expect(() => cartTotal(small, "NOPE")).toThrow(InvalidDiscountError);
+});
+
+test("checkoutSummary passes the code through", () => {
+  expect(checkoutSummary(small, "FREESHIP")).toBe("Total: $24.00");
+});

