+++ b/test/cron.test.ts
@@ -0,0 +1,31 @@
+import { expect, test } from "bun:test";
+import { CronError, nextRun } from "../src/cron";
+
+const at = (expr: string, from: string) => nextRun(expr, new Date(from)).toISOString();
+
+test("steps and ranges in the minute field", () => {
+  expect(at("*/15 * * * *", "2026-01-01T00:00:00Z")).toBe("2026-01-01T00:15:00.000Z");
+  expect(at("10-50/20 * * * *", "2026-01-01T00:10:30Z")).toBe("2026-01-01T00:30:00.000Z");
+});
+
+test("last day and classic day OR rule", () => {
+  expect(at("0 0 L * 1", "2026-02-01T00:00:00Z")).toBe("2026-02-02T00:00:00.000Z");
+  expect(at("0 0 * 2 5L", "2026-01-01T00:00:00Z")).toBe("2026-02-27T00:00:00.000Z");
+});
+
+test("nth weekday specials", () => {
+  expect(at("0 0 * * FRI#3", "2026-01-01T00:00:00Z")).toBe("2026-01-16T00:00:00.000Z");
+  expect(at("0 0 * * 0#5", "2026-01-01T00:00:00Z")).toBe("2026-03-29T00:00:00.000Z");
+});
+
+test("aliases are case-insensitive", () => {
+  expect(at("@DAILY", "2026-01-01T00:00:30Z")).toBe("2026-01-02T00:00:00.000Z");
+});
+
+test("invalid expressions throw CronError", () => {
+  expect(() => nextRun("5/15 * * * *", new Date(0))).toThrow(CronError);
+  expect(() => nextRun("5-1 * * * *", new Date(0))).toThrow(CronError);
+  expect(() => nextRun("0 0 * * 8", new Date(0))).toThrow(CronError);
+  expect(() => nextRun("0 0 5#3 * *", new Date(0))).toThrow(CronError);
+  expect(() => nextRun("0 0 30 2 *", new Date(0))).toThrow(CronError);
+});

