diff --git a/sched/plan_test.go b/sched/plan_test.go
new file mode 100644
index 0000000..29d8fa2
--- /dev/null
+++ b/sched/plan_test.go
@@ -0,0 +1,205 @@
+package sched
+
+import (
+	"errors"
+	"fmt"
+	"reflect"
+	"strconv"
+	"testing"
+	"time"
+)
+
+func TestPlanBatches(t *testing.T) {
+	got, err := Plan(map[string][]string{
+		"app":  {"lib", "util", "lib"},
+		"lib":  {"util"},
+		"util": nil,
+		"doc":  {},
+	})
+	if err != nil {
+		t.Fatal(err)
+	}
+	want := [][]string{{"doc", "util"}, {"lib"}, {"app"}}
+	if !reflect.DeepEqual(got, want) {
+		t.Fatalf("Plan = %v, want %v", got, want)
+	}
+}
+
+func TestPlanEmpty(t *testing.T) {
+	for _, m := range []map[string][]string{nil, {}} {
+		got, err := Plan(m)
+		if err != nil || got == nil || len(got) != 0 {
+			t.Fatalf("Plan(empty) = %v, %v", got, err)
+		}
+	}
+}
+
+func TestPlanUnknownBeforeCycle(t *testing.T) {
+	_, err := Plan(map[string][]string{
+		"z": {"w"},
+		"w": {"z", "q", "b"},
+		"b": {"zz"},
+		"a": {"zz"},
+	})
+	var ue *UnknownDepError
+	if !errors.As(err, &ue) || ue.Task != "a" || ue.Dep != "zz" {
+		t.Fatalf("err = %v", err)
+	}
+	if ue.Error() != `task "a" depends on unknown task "zz"` {
+		t.Fatalf("Error() = %q", ue.Error())
+	}
+}
+
+func TestPlanCycleCanonical(t *testing.T) {
+	_, err := Plan(map[string][]string{
+		"p": {"r", "q"},
+		"q": {"s"},
+		"s": {"p"},
+		"r": {"p"},
+	})
+	var ce *CycleError
+	if !errors.As(err, &ce) {
+		t.Fatalf("err = %v", err)
+	}
+	want := []string{"p", "q", "s", "p"}
+	if !reflect.DeepEqual(ce.Path, want) {
+		t.Fatalf("Path = %v, want %v", ce.Path, want)
+	}
+	if ce.Error() != "dependency cycle: p -> q -> s -> p" {
+		t.Fatalf("Error() = %q", ce.Error())
+	}
+}
+
+func TestPlanSelfLoop(t *testing.T) {
+	_, err := Plan(map[string][]string{"a": {}, "b": {"b"}})
+	var ce *CycleError
+	if !errors.As(err, &ce) || !reflect.DeepEqual(ce.Path, []string{"b", "b"}) {
+		t.Fatalf("err = %v", err)
+	}
+}
+
+func TestSimulateBasic(t *testing.T) {
+	s, err := Simulate(map[string]Task{
+		"a": {Duration: 3},
+		"b": {Deps: []string{"a"}, Duration: 2},
+		"c": {Duration: 5, Priority: 1},
+		"d": {Deps: []string{"b", "c"}, Duration: 1},
+	}, 2)
+	if err != nil {
+		t.Fatal(err)
+	}
+	// c has higher priority so it starts first on worker 0; a on worker 1.
+	want := map[string]Slot{
+		"c": {Start: 0, End: 5, Worker: 0},
+		"a": {Start: 0, End: 3, Worker: 1},
+		"b": {Start: 3, End: 5, Worker: 1},
+		"d": {Start: 5, End: 6, Worker: 0},
+	}
+	if !reflect.DeepEqual(s.Slots, want) {
+		t.Fatalf("Slots = %v", s.Slots)
+	}
+	if s.Makespan != 6 {
+		t.Fatalf("Makespan = %d", s.Makespan)
+	}
+	// weight(b) == weight(c) == 5; the tie goes to the smaller name.
+	if !reflect.DeepEqual(s.CriticalPath, []string{"a", "b", "d"}) {
+		t.Fatalf("CriticalPath = %v", s.CriticalPath)
+	}
+}
+
+func TestSimulateErrors(t *testing.T) {
+	if _, err := Simulate(map[string]Task{"a": {Duration: 1}}, 0); !errors.Is(err, ErrNoWorkers) {
+		t.Fatalf("err = %v", err)
+	}
+	_, err := Simulate(map[string]Task{"b": {Duration: 0}, "a": {Duration: -1}}, 1)
+	var de *InvalidDurationError
+	if !errors.As(err, &de) || de.Task != "a" || de.Error() != `task "a" has a non-positive duration` {
+		t.Fatalf("err = %v", err)
+	}
+	_, err = Simulate(map[string]Task{"a": {Deps: []string{"a"}, Duration: 1}}, 1)
+	var ce *CycleError
+	if !errors.As(err, &ce) {
+		t.Fatalf("err = %v", err)
+	}
+}
+
+func TestSimulateEmpty(t *testing.T) {
+	s, err := Simulate(nil, 3)
+	if err != nil || s.Slots == nil || s.CriticalPath == nil || s.Makespan != 0 {
+		t.Fatalf("Simulate(empty) = %+v, %v", s, err)
+	}
+}
+
+func TestScaleChainAndRing(t *testing.T) {
+	const n = 200000
+	deps := make(map[string][]string, n)
+	for i := 0; i < n; i++ {
+		var d []string
+		for k := 1; k <= 5 && i-k >= 0; k++ {
+			d = append(d, "t"+strconv.Itoa(i-k))
+		}
+		deps["t"+strconv.Itoa(i)] = d
+	}
+	start := time.Now()
+	if _, err := Plan(deps); err != nil {
+		t.Fatal(err)
+	}
+	tasks := make(map[string]Task, n)
+	for k, v := range deps {
+		tasks[k] = Task{Deps: v, Duration: 1 + len(v)}
+	}
+	if _, err := Simulate(tasks, 8); err != nil {
+		t.Fatal(err)
+	}
+	if el := time.Since(start); el > 4*time.Second {
+		t.Fatalf("too slow: %v", el)
+	}
+
+	// Ring of 100000 with a chain hanging off it.
+	ring := make(map[string][]string)
+	const r = 100000
+	for i := 0; i < r; i++ {
+		ring["r"+strconv.Itoa(i)] = []string{"r" + strconv.Itoa((i+1)%r)}
+	}
+	for i := 0; i < r; i++ {
+		ring["c"+strconv.Itoa(i)] = []string{"r0"}
+		if i > 0 {
+			ring["c"+strconv.Itoa(i)] = []string{"c" + strconv.Itoa(i-1)}
+		}
+	}
+	start = time.Now()
+	_, err := Plan(ring)
+	var ce *CycleError
+	if !errors.As(err, &ce) || len(ce.Path) != r+1 {
+		t.Fatalf("ring err = %v", err)
+	}
+	if el := time.Since(start); el > 2*time.Second {
+		t.Fatalf("ring too slow: %v", el)
+	}
+}
+
+func TestScaleManyTwoCycles(t *testing.T) {
+	m := make(map[string][]string)
+	for i := 0; i < 50000; i++ {
+		a, b := fmt.Sprintf("x%d-a", i), fmt.Sprintf("x%d-b", i)
+		m[a] = []string{b}
+		m[b] = []string{a}
+	}
+	for i := 0; i < 100000; i++ {
+		name := fmt.Sprintf("chain%d", i)
+		if i == 0 {
+			m[name] = []string{"x0-a"}
+		} else {
+			m[name] = []string{fmt.Sprintf("chain%d", i-1)}
+		}
+	}
+	start := time.Now()
+	_, err := Plan(m)
+	var ce *CycleError
+	if !errors.As(err, &ce) || ce.Path[0] != "x0-a" {
+		t.Fatalf("err = %v", err)
+	}
+	if el := time.Since(start); el > 2*time.Second {
+		t.Fatalf("too slow: %v", el)
+	}
+}

n() {
