+    assert_eq!(ev("(1 + 2"), Err(EvalError::Parse { pos: 6 }));
+    assert_eq!(ev("1 +"), Err(EvalError::Parse { pos: 3 }));
+    assert_eq!(ev("max(1"), Err(EvalError::Parse { pos: 5 }));
