+}
+
+#[test]
+fn loki_wall_parse_error_wins_over_eval_errors() {
+    assert_eq!(ev("q/0 )"), Err(EvalError::Parse { pos: 4 }));
+    assert_eq!(ev("foo(q"), Err(EvalError::Parse { pos: 5 }));
+    assert_eq!(ev("foo(q) )"), Err(EvalError::Parse { pos: 7 }));
+}
+
+#[test]
+fn loki_wall_evaluation_order_and_errors() {
+    assert_eq!(ev("q + 1/0"), Err(EvalError::UnknownVar("q".to_string())));
+    assert_eq!(ev("1/0 + q"), Err(EvalError::DivByZero));
+    assert_eq!(ev("1/-0.0"), Err(EvalError::DivByZero));
+    assert_eq!(ev("1 % 0"), Err(EvalError::DivByZero));
+    assert_eq!(ev("1 % -0.0"), Err(EvalError::DivByZero));
+    assert_eq!(ev("8/4"), Ok(2.0));
+    assert_eq!(ev("-7 % 3"), Ok(-1.0));
+    assert_eq!(ev("7.5 % 2"), Ok(1.5));
+}
+
+#[test]
+fn loki_wall_functions() {
+    assert_eq!(ev("min(3,1,2)"), Ok(1.0));
+    assert_eq!(ev("max(3,1,2)"), Ok(3.0));
+    assert_eq!(ev("min(5)"), Ok(5.0));
+    assert_eq!(ev("max(x,y)"), Ok(4.0));
+    assert_eq!(ev("abs(-4)"), Ok(4.0));
+    assert_eq!(ev("sqrt(16)"), Ok(4.0));
+    assert_eq!(ev("min (1, 2)"), Ok(1.0));
+    assert_eq!(ev("sqrt"), Err(EvalError::UnknownVar("sqrt".to_string())));
+    assert_eq!(ev("min(q)"), Err(EvalError::UnknownVar("q".to_string())));
