+    assert_eq!(ev("foo(q)"), Err(EvalError::UnknownFunc("foo".to_string())));
+    assert_eq!(ev("foo(1, 2)"), Err(EvalError::UnknownFunc("foo".to_string())));
+    assert_eq!(ev("x(1)"), Err(EvalError::UnknownFunc("x".to_string())));
+}
+
+#[test]
+fn loki_wall_arity_checked_before_arguments() {
