+    assert!(d < Duration::from_secs(2));
+    let bad = format!("{}-3{}", "abs(".repeat(n), ")".repeat(n - 1));
+    assert_eq!(ev(&bad), Err(EvalError::Parse { pos: bad.len() }));
+}
+
+#[test]
+fn loki_wall_deep_nested_max_calls() {
+    let n = 100000;
+    let s = format!("{}5{}", "max(1, ".repeat(n), ")".repeat(n));
+    let (r, d) = timed(&s);
+    assert_eq!(r, Ok(5.0));
+    assert!(d < Duration::from_secs(2));
+    let bad = format!("{}5", "max(1, ".repeat(n));
+    assert_eq!(ev(&bad), Err(EvalError::Parse { pos: bad.len() }));
+}
+
+#[test]
+fn loki_wall_deep_unary_minus() {
+    let n = 100000;
+    let s = format!("{}1", "-".repeat(n));
+    let (r, d) = timed(&s);
+    assert_eq!(r, Ok(1.0));
+    assert!(d < Duration::from_secs(2));
+    let bad = format!("{})", "-".repeat(n));
+    assert_eq!(ev(&bad), Err(EvalError::Parse { pos: n }));
+}
+
+#[test]
+fn loki_wall_deep_power_chain() {
+    let n = 100000;
+    let s = format!("{}1", "1^".repeat(n));
+    let (r, d) = timed(&s);
+    assert_eq!(r, Ok(1.0));
+    assert!(d < Duration::from_secs(2));
+    let bad = format!("{})", "1^".repeat(n));
+    assert_eq!(ev(&bad), Err(EvalError::Parse { pos: 2 * n }));
+}
+
+#[test]
+fn loki_wall_deep_long_sum() {
+    let n = 200000;
+    let s = format!("{}1", "1+".repeat(n - 1));
+    let (r, d) = timed(&s);
+    assert_eq!(r, Ok(200000.0));
+    assert!(d < Duration::from_secs(2));
+    let bad = format!("{})", "1+".repeat(n - 1));
+    assert_eq!(ev(&bad), Err(EvalError::Parse { pos: 2 * (n - 1) }));
+}
+
+#[test]
+fn loki_wall_deep_repeated_parenthesized_terms() {
+    let n = 100000;
+    let s = "(1)".repeat(n);
+    let (r, d) = timed(&s);
+    assert_eq!(r, Ok(1.0));
+    assert!(d < Duration::from_secs(2));
+    let bad = format!("{})", s);
+    assert_eq!(ev(&bad), Err(EvalError::Parse { pos: 3 * n }));
+}

