+use intervalkit::Bound::{Closed as C, Open as O};
+use intervalkit::{Bound, IntervalSet};
+use std::time::Instant;
+
+#[test]
+fn empty_intervals_are_ignored() {
+    let mut s = IntervalSet::new();
+    s.insert(O(2), O(2));
+    s.insert(C(2), O(2));
+    s.insert(O(2), C(2));
+    s.insert(C(3), C(2));
+    assert!(s.is_empty());
+    assert_eq!(s.ranges(), Vec::<(Bound, Bound)>::new());
+    assert_eq!(s.to_string(), "{}");
+    s.insert(C(2), C(2));
+    assert!(!s.is_empty());
+}
+
+#[test]
+fn open_interval_on_real_line_is_non_empty() {
+    let mut s = IntervalSet::new();
+    s.insert(O(2), O(3));
+    assert!(s.contains(2.5));
+    assert!(!s.contains(2.0));
+    assert!(!s.contains(3.0));
+    assert!(!s.is_empty());
+}
+
+#[test]
+fn closed_single_point_is_canonical() {
+    let mut s = IntervalSet::new();
+    s.insert(C(2), C(2));
+    assert_eq!(s.ranges(), vec![(C(2), C(2))]);
+    assert!(s.contains(2.0));
+    assert!(!s.contains(2.5));
+}
+
+#[test]
+fn touching_closed_and_half_open_merge() {
+    let mut s = IntervalSet::new();
+    s.insert(C(1), O(3));
+    s.insert(C(3), C(5));
+    assert_eq!(s.ranges(), vec![(C(1), C(5))]);
+    assert_eq!(s.to_string(), "{[1,5]}");
+}
+
+#[test]
+fn closed_and_open_union_merge_into_half_open() {
+    let mut s = IntervalSet::new();
+    s.insert(C(1), C(3));
+    s.insert(O(3), O(5));
+    assert_eq!(s.ranges(), vec![(C(1), O(5))]);
+}
+
+#[test]
+fn open_and_point_union_merge_into_half_open_other_side() {
+    let mut s = IntervalSet::new();
+    s.insert(O(1), O(3));
+    s.insert(C(3), C(3));
+    assert_eq!(s.ranges(), vec![(O(1), C(3))]);
+}
+
+#[test]
+fn missing_endpoint_keeps_intervals_separate() {
+    let mut s = IntervalSet::new();
+    s.insert(O(1), O(3));
+    s.insert(O(3), O(5));
+    assert_eq!(s.ranges(), vec![(O(1), O(3)), (O(3), O(5))]);
+    assert_eq!(s.to_string(), "{(1,3), (3,5)}");
+
+    let mut t = IntervalSet::new();
+    t.insert(C(1), O(3));
+    t.insert(O(3), C(5));
+    assert_eq!(t.ranges(), vec![(C(1), O(3)), (O(3), C(5))]);
+    assert!(!t.contains(3.0));
+}
+
+#[test]
+fn remove_closed_point_splits_interval() {
+    let mut s = IntervalSet::new();
+    s.insert(C(1), C(5));
+    s.remove(C(2), C(2));
+    assert_eq!(s.ranges(), vec![(C(1), O(2)), (O(2), C(5))]);
+    assert!(!s.contains(2.0));
+    assert!(s.contains(1.5));
+}
+
+#[test]
+fn remove_open_interval_keeps_endpoints() {
+    let mut s = IntervalSet::new();
+    s.insert(C(1), C(5));
+    s.remove(O(2), O(4));
+    assert_eq!(s.ranges(), vec![(C(1), C(2)), (C(4), C(5))]);
+    assert_eq!(s.to_string(), "{[1,2], [4,5]}");
+}
+
+#[test]
+fn remove_empty_interval_is_noop() {
+    let mut s = IntervalSet::new();
+    s.insert(C(1), C(5));
+    s.remove(O(3), O(3));
+    s.remove(C(4), C(2));
+    assert_eq!(s.ranges(), vec![(C(1), C(5))]);
+}
+
+#[test]
+fn contains_respects_bound_kinds() {
+    let mut s = IntervalSet::new();
+    s.insert(C(1), O(3));
+    assert!(s.contains(1.0));
+    assert!(s.contains(2.999));
+    assert!(!s.contains(3.0));
+    assert!(!s.contains(0.999));
+}
+
+#[test]
+fn measure_sums_lengths_and_ignores_points() {
+    let mut s = IntervalSet::new();
+    s.insert(C(1), O(5));
+    s.insert(C(7), C(7));
+    assert_eq!(s.measure(), 4);
+    assert_ne!(s.measure(), 5);
+}
+
+#[test]
+fn measure_does_not_overflow_for_i64_extremes() {
+    let mut s = IntervalSet::new();
+    s.insert(C(i64::MIN), C(i64::MAX));
+    assert_eq!(s.measure(), i64::MAX as i128 - i64::MIN as i128);
+    assert_eq!(s.ranges(), vec![(C(i64::MIN), C(i64::MAX))]);
+    assert!(s.contains(i64::MIN as f64));
+    assert!(s.contains(i64::MAX as f64));
+}
+
+#[test]
+fn remove_at_i64_extremes_keeps_correct_remainder() {
+    let mut s = IntervalSet::new();
+    s.insert(C(i64::MIN), C(i64::MAX));
+    s.remove(C(i64::MIN), C(-1));
+    assert_eq!(s.ranges(), vec![(O(-1), C(i64::MAX))]);
+    assert!(!s.contains(-1.0));
+    assert!(s.contains(0.0));
+}
+
+#[test]
+fn complement_of_example_window() {
+    let mut s = IntervalSet::new();
+    s.insert(C(2), O(4));
+    s.insert(O(6), C(8));
+    assert_eq!(
+        s.complement(C(0), C(10)),
+        vec![(C(0), O(2)), (C(4), C(6)), (O(8), C(10))]
+    );
+}
+
+#[test]
+fn complement_empty_when_window_empty_or_covered() {
+    let mut s = IntervalSet::new();
+    s.insert(C(1), O(5));
+    assert_eq!(s.complement(O(3), O(3)), Vec::<(Bound, Bound)>::new());
+    assert_eq!(s.complement(C(2), C(3)), Vec::<(Bound, Bound)>::new());
+    assert_ne!(s.complement(C(0), C(3)), Vec::<(Bound, Bound)>::new());
+}
+
+#[test]
+fn display_formats_canonical_intervals() {
+    let mut s = IntervalSet::new();
+    s.insert(C(7), C(7));
+    s.insert(C(1), O(3));
+    s.insert(O(4), C(5));
+    assert_eq!(s.to_string(), "{[1,3), (4,5], [7,7]}");
+
+    let mut t = IntervalSet::new();
+    t.insert(O(-3), C(0));
+    assert_eq!(t.to_string(), "{(-3,0]}");
+    assert_ne!(t.to_string(), "{(-3, 0]}");
+}
+
+#[test]
+fn large_workload_runs_within_budget() {
+    let mut seed: u64 = 0x9E37_79B9_7F4A_7C15;
+    let mut next = move || {
+        seed ^= seed << 13;
+        seed ^= seed >> 7;
+        seed ^= seed << 17;
+        seed
+    };
+    let mut s = IntervalSet::new();
+    let start = Instant::now();
+    for i in 0..300_000u64 {
+        let base = 1_000_000_000i64 - (i as i64) * 3333;
+        let jitter = (next() % 2001) as i64 - 1000;
+        let lo = base + jitter;
+        let len = (next() % 1001) as i64;
+        let hi = lo + len;
+        if i % 2 == 0 {
+            s.insert(C(lo), O(hi));
+        } else {
+            s.insert(O(lo), C(hi));
+        }
+        if i % 3 == 0 {
+            s.remove(C(lo), C(hi));
+        }
+        let p = (next() % 1_000_000_001) as f64;
+        let _ = s.contains(p);
+    }
+    let elapsed = start.elapsed();
+    assert!(elapsed.as_secs_f64() < 3.0, "took {:?}", elapsed);
+    assert!(!s.is_empty());
+}

