+use romankit::{from_roman, to_roman, RomanError};
+use std::collections::HashSet;
+
+const ALPHA: [char; 7] = ['I', 'V', 'X', 'L', 'C', 'D', 'M'];
+
+fn candidates() -> Vec<String> {
+    let mut out = Vec::new();
+    for len in 1..=5u32 {
+        let total = 7usize.pow(len);
+        for mut idx in 0..total {
+            let mut s = String::new();
+            for _ in 0..len {
+                s.push(ALPHA[idx % 7]);
+                idx /= 7;
+            }
+            out.push(s);
+        }
+    }
+    out
+}
+
+#[test]
+fn subtractive_numerals_parse_correctly() {
+    assert_eq!(from_roman("IV").ok(), Some(4));
+    assert_eq!(from_roman("IX").ok(), Some(9));
+    assert_eq!(from_roman("XIX").ok(), Some(19));
+    assert_eq!(from_roman("XL").ok(), Some(40));
+    assert_eq!(from_roman("XC").ok(), Some(90));
+    assert_eq!(from_roman("CD").ok(), Some(400));
+    assert_eq!(from_roman("CM").ok(), Some(900));
+    assert_eq!(from_roman("MCMXCIV").ok(), Some(1994));
+    assert!(!matches!(from_roman("IV"), Ok(6)));
+    assert!(!matches!(from_roman("XIX"), Ok(21)));
+}
+
+#[test]
+fn non_canonical_strings_are_rejected() {
+    let bad = [
+        "IIII", "IC", "VX", "MMMM", "IIV", "XM", "VV", "LL", "DM", "IM", "IIX", "VL", "XXXX",
+        "CCCC", "DD", "XXXXX",
+    ];
+    for s in bad {
+        assert!(
+            matches!(from_roman(s), Err(RomanError::NonCanonical)),
+            "expected NonCanonical for {}",
+            s
+        );
+    }
+}
+
+#[test]
+fn empty_string_is_empty_error() {
+    assert!(matches!(from_roman(""), Err(RomanError::Empty)));
+    assert!(from_roman("").is_err());
+}
+
+#[test]
+fn invalid_chars_reported_before_noncanonical() {
+    assert!(matches!(from_roman("xiv"), Err(RomanError::InvalidChar('x'))));
+    assert!(matches!(from_roman("XI V"), Err(RomanError::InvalidChar(' '))));
+    assert!(matches!(from_roman("xY"), Err(RomanError::InvalidChar('x'))));
+    assert!(matches!(from_roman("IIIIx"), Err(RomanError::InvalidChar('x'))));
+    assert!(matches!(from_roman("IVq?"), Err(RomanError::InvalidChar('q'))));
+}
+
+#[test]
+fn to_roman_rejects_out_of_range() {
+    assert!(matches!(to_roman(0), Err(RomanError::OutOfRange)));
+    assert!(matches!(to_roman(4000), Err(RomanError::OutOfRange)));
+    assert!(matches!(to_roman(u32::MAX), Err(RomanError::OutOfRange)));
+    assert!(to_roman(0).ok() != Some(String::new()));
+    assert!(to_roman(4000).ok() != Some("MMMM".to_string()));
+}
+
+#[test]
+fn to_roman_canonical_samples() {
+    assert_eq!(to_roman(1).ok(), Some("I".to_string()));
+    assert_eq!(to_roman(4).ok(), Some("IV".to_string()));
+    assert_eq!(to_roman(9).ok(), Some("IX".to_string()));
+    assert_eq!(to_roman(40).ok(), Some("XL".to_string()));
+    assert_eq!(to_roman(1994).ok(), Some("MCMXCIV".to_string()));
+    assert_eq!(to_roman(3888).ok(), Some("MMMDCCCLXXXVIII".to_string()));
+    assert_eq!(to_roman(3999).ok(), Some("MMMCMXCIX".to_string()));
+}
+
+#[test]
+fn round_trip_all_valid_numbers() {
+    for n in 1..=3999u32 {
+        let s = match to_roman(n) {
+            Ok(s) => s,
+            Err(_) => panic!("to_roman({}) failed", n),
+        };
+        assert_eq!(from_roman(&s).ok(), Some(n), "round trip failed for {}", s);
+    }
+}
+
+#[test]
+fn from_roman_accepts_exactly_canonical_forms() {
+    let canonical: HashSet<String> = (1..=3999u32)
+        .map(|n| to_roman(n).expect("valid range"))
+        .collect();
+    for s in candidates() {
+        let is_canon = canonical.contains(&s);
+        match from_roman(&s) {
+            Ok(n) => {
+                assert!(is_canon, "accepted non-canonical {}", s);
+                assert_eq!(to_roman(n).ok(), Some(s.clone()));
+            }
+            Err(RomanError::NonCanonical) => {
+                assert!(!is_canon, "rejected canonical {}", s);
+            }
+            Err(_) => panic!("unexpected error kind for {}", s),
+        }
+    }
+}
+
+#[test]
+fn from_roman_never_reports_out_of_range() {
+    for s in ["MMMM", "MMMMM", "MMMMCM", "IIII", "", "xiv"] {
+        assert!(!matches!(from_roman(s), Err(RomanError::OutOfRange)));
+    }
+    for n in 1..=3999u32 {
+        let s = to_roman(n).expect("valid range");
+        assert!(!matches!(from_roman(&s), Err(RomanError::OutOfRange)));
+    }
+}
