+    assert_eq!(
+        Shape::parse("rect", &[1.0]),
+        Err(ShapeError::WrongParamCount { expected: 2, got: 1 })
+    );
+    assert_eq!(
+        Shape::parse("circle", &[-1.0]),
+        Err(ShapeError::NegativeDimension)
+    );
+    assert_eq!(
+        Shape::parse("triangle", &[1.0, 1.0, 5.0]),
+        Err(ShapeError::InvalidTriangle)
+    );
+}
+
+#[test]
+fn parse_square_becomes_rect() {
+    assert_eq!(
+        Shape::parse("SQUARE", &[2.0]),
+        Ok(Shape::Rect { w: 2.0, h: 2.0 })
+    );
+}
+
+#[test]
+fn degenerate_triangle_has_zero_area() {
+    assert_eq!(
+        Shape::Triangle { a: 1.0, b: 2.0, c: 3.0 }.area(),
+        Ok(0.0)
+    );
+}
+
+#[test]
+fn display_messages() {
+    assert_eq!(
+        ShapeError::WrongParamCount { expected: 3, got: 0 }.to_string(),
+        "expected 3 params, got 0"
+    );
+    assert_eq!(
+        ShapeError::NegativeDimension.to_string(),
+        "dimensions must be non-negative"
+    );
+    assert_eq!(
+        ShapeError::InvalidTriangle.to_string(),
+        "sides do not form a triangle"
+    );
+}
+
+#[test]
+fn direct_shape_validation() {
+    assert_eq!(
+        Shape::Rect { w: -1.0, h: 1.0 }.perimeter(),
+        Err(ShapeError::NegativeDimension)
+    );
+    assert_eq!(
+        Shape::Triangle { a: 1.0, b: 1.0, c: 5.0 }.area(),
+        Err(ShapeError::InvalidTriangle)
+    );
+}

