+  expect(nextRun("0 0 29 2 *", utc("2027-03-01T00:00Z")).toISOString()).toBe("2028-02-29T00:00:00.000Z");
+  expect(() => nextRun("0 0 30 2 *", utc("2026-11-02T00:00Z"))).toThrow(CronError);
+  expect(() => nextRun("0 0 31W 2 *", utc("2026-11-02T00:00Z"))).toThrow(CronError);
+});
+
+test("aliases are case-insensitive and nothing else with @ is accepted", () => {
+  expect(nextRun("@daily", utc("2026-11-02T10:30Z")).toISOString()).toBe("2026-11-03T00:00:00.000Z");
+  expect(nextRun("@HOURLY", utc("2026-11-02T10:30Z")).toISOString()).toBe("2026-11-02T11:00:00.000Z");
+  expect(nextRun("@yearly", utc("2026-11-02T00:00Z")).toISOString()).toBe("2027-01-01T00:00:00.000Z");
+  expect(nextRun("@Annually", utc("2026-11-02T00:00Z")).toISOString()).toBe("2027-01-01T00:00:00.000Z");
+  expect(nextRun("@monthly", utc("2026-11-02T00:00Z")).toISOString()).toBe("2026-12-01T00:00:00.000Z");
+  expect(nextRun("@weekly", utc("2026-11-02T00:00:30Z")).toISOString()).toBe("2026-11-08T00:00:00.000Z");
+  expect(() => nextRun("@reboot", utc("2026-11-02T00:00Z"))).toThrow(CronError);
+  expect(() => nextRun("@daily * * * * *", utc("2026-11-02T00:00Z"))).toThrow(CronError);
+});
+
+test("result drops seconds, is strictly after from, and does not mutate from", () => {
+  const from = utc("2026-11-02T10:07:45.500Z");
+  const before = from.getTime();
+  const next = nextRun("* * * * *", from);
+  expect(next.toISOString()).toBe("2026-11-02T10:08:00.000Z");
+  expect(next).not.toBe(from);
+  expect(from.getTime()).toBe(before);
+  expect(nextRun("30 10 * * *", utc("2026-11-02T10:30:00Z")).toISOString()).toBe("2026-11-03T10:30:00.000Z");
+});
+
+test("CronError is an Error subclass", () => {
+  let caught: unknown = null;
+  try {
+    nextRun("1 2 3", utc("2026-01-01T00:00Z"));
+  } catch (e) {
+    caught = e;
+  }
+  expect(caught).toBeInstanceOf(CronError);
+  expect(caught).toBeInstanceOf(Error);
+});
+
+test("3000 calls across rare schedules finish under 2 seconds", () => {
+  const schedules = ["0 0 29 2 1", "59 23 31 12 5L", "0 0 LW 2 *", "30 4 15W * 1#5", "0 0 29 2 *"];
+  let thrown = 0;
+  let produced = 0;
+  const started = performance.now();
+  for (let i = 0; i < 3000; i++) {
+    const expr = schedules[i % schedules.length];
+    const from = new Date(Date.UTC(2000 + (i % 100), (i * 7) % 12, 1 + ((i * 13) % 28), (i * 5) % 24, (i * 11) % 60));
+    try {
+      nextRun(expr, from);
+      produced++;
+    } catch (e) {
+      if (!(e instanceof CronError)) throw e;
+      thrown++;
+    }
+  }
+  const elapsed = performance.now() - started;
+  expect(produced + thrown).toBe(3000);
+  expect(thrown).toBeGreaterThan(0);
+  expect(elapsed).toBeLessThan(2000);
+});

